import re

_UNITS = {
    'w': 604800, 'week': 604800, 'weeks': 604800,
    'd': 86400, 'day': 86400, 'days': 86400,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
}


def _finish(total: float) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(round(total))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty input")

    # bare non-negative integer
    if re.fullmatch(r"\d+", s):
        return _finish(int(s))

    # ISO 8601 duration
    if s[0] in ('P', 'p'):
        return _parse_iso(s)

    # clock notation
    if ':' in s:
        return _parse_clock(s)

    # number+unit components
    return _parse_components(s)


def _parse_iso(s: str) -> int:
    m = re.fullmatch(
        r"[Pp](?:(\d+(?:\.\d+)?)W)?(?:(\d+(?:\.\d+)?)D)?"
        r"(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?",
        s, re.IGNORECASE,
    )
    if not m or not any(m.groups()):
        raise ValueError("invalid ISO 8601 duration: %r" % s)
    weeks, days, hours, minutes, seconds = m.groups()
    total = 0.0
    total += float(weeks or 0) * 604800
    total += float(days or 0) * 86400
    total += float(hours or 0) * 3600
    total += float(minutes or 0) * 60
    total += float(seconds or 0)
    return _finish(total)


def _parse_clock(s: str) -> int:
    parts = s.split(':')
    if len(parts) not in (2, 3):
        raise ValueError("invalid clock notation: %r" % s)
    try:
        nums = [float(p) for p in parts]
    except ValueError:
        raise ValueError("invalid clock notation: %r" % s)
    if any(n < 0 for n in nums):
        raise ValueError("negative duration")
    if len(parts) == 3:
        h, m, sec = nums
    else:
        h = 0.0
        m, sec = nums
    return _finish(h * 3600 + m * 60 + sec)


def _parse_components(s: str) -> int:
    matches = re.findall(r"(\d+(?:\.\d+)?)\s*([a-zA-Z]+)", s)
    if not matches:
        raise ValueError("invalid duration: %r" % s)
    # ensure the whole string is consumed by components
    stripped = re.sub(r"(\d+(?:\.\d+)?)\s*([a-zA-Z]+)", "", s)
    if stripped.strip():
        raise ValueError("invalid duration: %r" % s)
    total = 0.0
    for value, unit in matches:
        key = unit.lower()
        if key not in _UNITS:
            raise ValueError("unknown unit: %r" % unit)
        total += float(value) * _UNITS[key]
    return _finish(total)

